// n8n Code Node: Parser / Color-Fruit Resolver
// Mode: Run Once for All Items
// ไม่ใช้ COD เดาจำนวน และไม่สร้าง display_for_packer

const orders = $items('Make Webhook');
const productItems = $items('HTTP GET product_map_master');
const aliasItems = $items('HTTP GET product_alias_dictionary');
const productRows = productItems.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : (Array.isArray(i.json) ? i.json : [i.json]));
const aliasRows = aliasItems.flatMap(i => Array.isArray(i.json?.data) ? i.json.data : (Array.isArray(i.json) ? i.json : [i.json]));
const products = productRows.filter(Boolean);
const aliases = aliasRows.filter(Boolean);

const rules = [
  { group: 'GREEN_MENTHOL', words: ['เขียว', 'คาเขียว', 'คาเขีว', 'เขียวร้อยท่อ'], emoji: ['🟢', '🟩'], skus: ['CAVALLO_GREEN', 'MOND_GREEN', 'SIERRA_GREEN', 'SEVIOS_GREEN', 'VESS_GREEN', 'VESS_GREEN_SLIMS'] },
  { group: 'RED', words: ['แดง', 'คาแดง'], emoji: ['🔴', '🟥'], skus: ['CAVALLO_RED', 'SEVIOS_RED', 'SIERRA_RED', 'ROYAL_RED', 'VESS_RED'] },
  { group: 'WATERMELON', words: ['แตงโม', 'แตงโมแดง', 'watermelon'], emoji: ['🍉'], skus: ['OS_WATERMELON', 'CAVALLO_WATERMELON'] },
  { group: 'PURPLE_GRAPE', words: ['ม่วง', 'คาม่วง', 'คา ม่วง', 'องุ่น'], emoji: ['🟣', '🟪', '🍇'], skus: ['CAVALLO_TWIN_X_BALL', 'MILANO_PURPLE', 'OS_BLUEBERRY'] },
  { group: 'YELLOW_GOLD', words: ['ทอง', 'เหลือง', 'คาเหลือง'], emoji: ['🟡', '🟨'], skus: ['MOND_GOLD', 'VESS_GOLD'] },
  { group: 'MANGO', words: ['มะม่วง', 'mango'], emoji: ['🥭'], skus: ['OS_MANGO', 'CAVALLO_MANGO', 'VESS_CRUSH_MINT.X.MANGO'] },
  { group: 'BLUEBERRY', words: ['บลู', 'บูล', 'บูลเบอรื', 'บลูเบอร์รี่', 'blueberry'], emoji: ['🔵', '🟦', '🍇'], skus: ['OS_BLUEBERRY'] },
  { group: 'BLACK', words: ['ดำ', 'คาดำ'], emoji: ['⚫', '⬛'], skus: ['VESS_GREEN_BLACK', 'PLATINUM_BLACK', 'JHON_BLACK'] }
];

const norm = (v) => String(v ?? '').toLowerCase().normalize('NFC').replace(/[._()\[\]{}:：,，/\-]/g, ' ').replace(/\s+/g, ' ').trim();
const compact = (v) => norm(v).replace(/\s/g, '');
const skuOf = (r) => String(r.sku ?? r.SKU ?? r.product_sku ?? '').trim();
const rowText = (r) => [r.alias_text, r.alias, r.alias_norm, r.alias_norm_clean, r.th_name, r.product_name, r.product_name_th].filter(Boolean).join(' ');
const allRows = [...products, ...aliases];

function resolve(raw) {
  const text = String(raw ?? '');
  const n = compact(text);
  const groups = rules.filter(r => r.words.some(w => norm(text).includes(norm(w))) || r.emoji.some(e => text.includes(e)));
  const explicit = [...new Set(allRows.filter(r => {
    const sku = skuOf(r);
    const terms = [sku, rowText(r)].filter(Boolean);
    return terms.some(t => compact(t) && n.includes(compact(t)));
  }).map(skuOf).filter(Boolean))];
  const groupCandidates = [...new Set(groups.flatMap(g => g.skus))].filter(sku => products.length === 0 || products.some(p => skuOf(p) === sku));
  const candidates = explicit.length ? explicit : groupCandidates;
  const status = candidates.length === 0 ? 'SKU_DISCOVERY_REQUIRED' : candidates.length === 1 ? 'MATCHED' : 'AMBIGUOUS';
  const qtyMatch = text.match(/(?:^|\s)(\d+(?:\.\d+)?)\s*(?:คอต|คอตตอน|กล่อง|ชิ้น)?\s*$/iu);
  const quantity = qtyMatch ? Number(qtyMatch[1]) : null;
  return { text, groups, candidates, status, quantity };
}

return orders.map((item) => {
  const original = { ...item.json };
  const raw = original.sniper_x_text_clean ?? original.raw_message ?? original.raw ?? original.clean_text ?? original.alias ?? original.product_text ?? '';
  const r = resolve(raw);
  const preservedCod = original.cod_amount;
  return {
    json: {
      ...original,
      raw_order_for_discovery: raw,
      sensory_group: r.groups.length === 1 ? r.groups[0].group : r.groups.map(g => g.group),
      detected_color_keywords: r.groups.flatMap(g => g.words.filter(w => norm(raw).includes(norm(w)))),
      detected_emoji: r.groups.flatMap(g => g.emoji.filter(e => raw.includes(e))),
      candidate_skus: r.candidates,
      candidate_count: r.candidates.length,
      color_mapping_status: r.status,
      mapping_status: r.status === 'MATCHED' ? 'MATCHED' : r.status === 'AMBIGUOUS' ? 'CHECK_PRODUCT' : 'SKU_DISCOVERY_REQUIRED',
      quantity_from_product_text: r.quantity,
      mapping_reason: r.status === 'MATCHED' ? 'EXPLICIT_OR_SINGLE_MASTER_CANDIDATE' : r.status === 'AMBIGUOUS' ? 'MULTIPLE_CANDIDATES_NEED_BRAND_OR_VARIANT' : 'KEEP_ORDER_FOR_DISCOVERY',
      next_action: r.status === 'MATCHED' ? 'CHECK_COD' : 'ROUTE_TO_PRODUCT_REVIEW',
      cod_amount: preservedCod
    }
  };
});

// ข้อความส่งห้องงาน: ใช้ Display เดิมถ้ามี ห้ามสร้าง Display ใหม่
return $input.all().map(item => {
  const j = item.json;
  const status = j.mapping_status ?? j.color_mapping_status ?? 'CHECK_PRODUCT';
  const display = j.telegram_final_mapped ?? j.display_for_packer ?? null;
  const message = display ? display : `🔎 ${status}\n${j.raw_order_for_discovery ?? j.alias ?? j.raw ?? ''}\nCandidate: ${(j.candidate_skus ?? []).join(', ') || 'ยังไม่พบ SKU'}`;
  return { json: { ...j, telegram_text: message, telegram_route_status: status } };
});
